interface Page<T> {
  items: T[];
  nextCursor: string | null;
}

const PAGES: Record<string, Page<string>> = {
  start: { items: ["ORD-1", "ORD-2"], nextCursor: "b" },
  b: { items: ["ORD-3"], nextCursor: null },
};

async function fetchPage(cursor: string | null): Promise<Page<string>> {
  return PAGES[cursor ?? "start"] ?? { items: [], nextCursor: null };
}

async function* paginate<T>(fetch: (cursor: string | null) => Promise<Page<T>>): AsyncGenerator<T, void, undefined> {
  let cursor: string | null = null;
  do {
    const page = await fetch(cursor);
    yield* page.items;
    cursor = page.nextCursor;
  } while (cursor !== null);
}

const ids: string[] = [];
for await (const id of paginate(fetchPage)) ids.push(id);
console.log(ids.join(" "));

