async function collect<T>(source: AsyncIterable<T>, limit: number): Promise<T[]> {
  const items: T[] = [];
  if (limit <= 0) return items;
  for await (const item of source) {
    items.push(item);
    if (items.length >= limit) break;
  }
  return items;
}

let produced = 0;
async function* amounts(): AsyncGenerator<number, void, undefined> {
