function legacyGetRate(currency: string, callback: (error: Error | null, rate?: number) => void): void {
  setTimeout(() => {
    if (currency === "USD") callback(null, 1540.25);
    else if (currency === "XYZ") callback(new Error(`unknown currency ${currency}`));
    else callback(null);
  }, 5);
}

function getRate(currency: string): Promise<number> {
  return new Promise((resolve, reject) => {
    legacyGetRate(currency, (error, rate) => {
      if (error !== null) reject(error);
      else if (rate === undefined) reject(new Error("no rate"));
      else resolve(rate);
    });
  });
}

for (const currency of ["USD", "XYZ", "GHS"]) {
  try {
    console.log(currency, await getRate(currency));
  } catch (error) {
    console.log(currency, error instanceof Error ? error.message : error);
  }
}
